BEGIN READ ONLY; SET LOCAL statement_timeout='10s'; SELECT jsonb_build_object('captured_at',clock_timestamp(),'functions',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'definition',pg_get_functiondef(p.oid),'md5',md5(p.prosrc)) ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('apply_import_session','count_friends_tracking','fetch_club_bundle','fetch_friend_activity_for_title','shares_club_with','undo_import_session','_account_write_guard','_import_apply_outcome','begin_account_deletion','finalize_account_deletion','club_disclosure_signal_v1','bump_club_membership_epoch')),'counts',jsonb_build_object('anime_lists',(SELECT count(*) FROM public.anime_user_lists),'manga_lists',(SELECT count(*) FROM public.manga_user_lists),'retained_dev_auth',(SELECT count(*) FROM auth.users WHERE id='9625cae4-cd7c-44ff-9783-595b53464146'::uuid)),'cron',(SELECT jsonb_agg(jsonb_build_object('id',jobid,'schedule',schedule,'active',active,'command_md5',md5(command))) FROM cron.job)) AS dependency_source; ROLLBACK;
